// ECG export (docs/STANDARDS.md): DICOM 12-lead waveform and HL7 aECG, each read back to the same leads and samples.
// The trace is generated by the test helper, not real data, and nameless.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { tempDir } from './support/helpers.mjs';
import { generateEcg, writeWfdb } from './support/ecg-gen.mjs';
import { readRecord, toObservation } from '../ecg/server/wfdb.mjs';
import { leadsOf, toDicomWaveform, readDicomWaveform, toAecg, readAecg } from '../standards/server/ecg-export.mjs';
import { parse } from '../pacs/server/dicom.mjs';

test('ECG Observation -> DICOM waveform -> leads, and -> aECG -> leads, without loss', () => {
  const dir = tempDir('hd-ecgx-'); const rec = generateEcg({ rhythm: 'normal', seed: 3 }); writeWfdb(rec, dir, fs, path);
  const { observation } = toObservation(readRecord(dir, rec.name), { patientId: 'p1', importedAt: '2026-05-01T09:00:00.000Z' });
  const want = leadsOf(observation); assert.equal(want.length, 12);
  const bytes = toDicomWaveform(observation, { patientId: 'N340001', sex: 'female', birthDate: '1970-01-01' });
  const f = parse(bytes); assert.equal(f.str('SOPClassUID'), '1.2.840.10008.5.1.4.1.1.9.1.1', '12-Lead ECG Waveform Storage'); assert.equal(f.str('Modality'), 'ECG'); assert.equal(f.str('PatientName'), '');
  const back = readDicomWaveform(bytes);
  assert.deepEqual(back.map((l) => [l.code, l.samples.length]), want.map((l) => [l.code, Math.min(...want.map((x) => x.samples.length))]));
  for (let c = 0; c < 12; c += 1) { assert.deepEqual(back[c].samples, want[c].samples); assert.ok(Math.abs(back[c].factor - want[c].factor) < 1e-9); assert.equal(back[c].origin, want[c].origin); assert.ok(Math.abs(back[c].periodMs - want[c].periodMs) < 1e-6); }
  const xml = toAecg(observation, { patientId: 'N340001', sex: 'female' });
  assert.match(xml, /<AnnotatedECG /); assert.match(xml, /<name nullFlavor="MSK"\/>/);
  const a = readAecg(xml); assert.equal(a.leads.length, 12);
  for (let c = 0; c < 12; c += 1) { assert.equal(a.leads[c].code, String(want[c].code)); assert.deepEqual(a.leads[c].samples, want[c].samples); assert.equal(a.leads[c].factor, want[c].factor); }
});
